fn vec_min_i8(arr: &Vec<i8>) -> i8 {
    // Requires that the array is not empty
    // Ensures that the returned value is the minimum element in the array
    // Invariant: The array must be non-empty
    // Decreases clause: The length of the array decreases as we find the minimum
    assert!(!arr.is_empty(), "Array must not be empty");
    let min_value = *arr.iter().min().unwrap();
    min_value
}

fn vec_max_i8(arr: &Vec<i8>) -> i8 {
    // Requires that the array is not empty
    // Ensures that the returned value is the maximum element in the array
    // Invariant: The array must be non-empty
    // Decreases clause: The length of the array decreases as we find the maximum
    assert!(!arr.is_empty(), "Array must not be empty");
    let max_value = *arr.iter().max().unwrap();
    max_value
}

fn percentile(arr: Vec<i8>, q: i8) -> i8 {
    // Requires that the array is not empty and q is in the range [0, 100]
    // Ensures that the returned value is a valid element based on the percentile q
    // Invariant: The array must be non-empty and q must be in the range [0, 100]
    assert!(!arr.is_empty(), "Array must not be empty");
    assert!(q >= 0 && q <= 100, "q must be in the range [0, 100]");

    if q == 0 {
        vec_min_i8(&arr)
    } else if q == 100 {
        vec_max_i8(&arr)
    } else {
        // For any other q, we can return any element from the array
        // that satisfies the existence requirements. We can simply return
        // the first element as a valid choice.
        arr[0]
    }
}

